/**
 * Rendering of lazy runtime registries and TypeScript module augmentation.
 *
 * @module
 */
import path from 'node:path';

import { DEFAULT_SEARCH_CODEC, type SearchCodecName } from '../runtime/search-codec';
import type { PreparedSearchRoute } from './route-config';

/** Relative posix specifier for a generated file, with a `.js` extension. */
export function moduleSpecifier(fromFile: string, toFile: string): string {
  let relative = path.relative(path.dirname(fromFile), toFile);
  if (!relative.startsWith('.')) relative = `./${relative}`;

  return relative
    .split(path.sep)
    .join('/')
    .replace(/\.(?:d\.)?[cm]?[jt]sx?$/i, '.js');
}

function sortedRoutes(routes: ReadonlyArray<PreparedSearchRoute>): Array<PreparedSearchRoute> {
  return [...routes].sort((left, right) => left.route.path.localeCompare(right.route.path));
}

const reportedPathCollisions = new Set<string>();

/**
 * The registry is keyed by URL path, so two routes that validate search for the
 * same path at the same depth cannot both be reachable through `Link`,
 * `useNavigate` or `useValidatedSearch` — one silently wins. Warned about once
 * per pair so a dev server does not repeat it on every rebuild.
 */
function warnPathCollision(route: PreparedSearchRoute, winner: PreparedSearchRoute): void {
  const key = `${winner.route.id}\n${route.route.id}`;
  if (reportedPathCollisions.has(key)) return;
  reportedPathCollisions.add(key);

  console.warn(
    `[react-router-validated-search] Routes "${winner.route.id}" and "${route.route.id}" both validate search for path "${route.route.path}". Typed helpers will use "${winner.route.id}".`,
  );
}

function deepestRoutesByPath(
  routes: ReadonlyArray<PreparedSearchRoute>,
): Array<PreparedSearchRoute> {
  const routesById = new Map(
    routes.map((preparedRoute) => [preparedRoute.route.id, preparedRoute]),
  );
  const depthById = new Map<string, number>();

  function getDepth(preparedRoute: PreparedSearchRoute): number {
    const cached = depthById.get(preparedRoute.route.id);
    if (cached !== undefined) return cached;

    const parent = preparedRoute.route.parentId
      ? routesById.get(preparedRoute.route.parentId)
      : undefined;
    const depth = parent ? getDepth(parent) + 1 : 0;
    depthById.set(preparedRoute.route.id, depth);
    return depth;
  }

  const byPath = new Map<string, PreparedSearchRoute>();
  for (const preparedRoute of routes) {
    const current = byPath.get(preparedRoute.route.path);

    if (!current) {
      byPath.set(preparedRoute.route.path, preparedRoute);
      continue;
    }

    const depth = getDepth(preparedRoute);
    const currentDepth = getDepth(current);

    if (depth > currentDepth) {
      byPath.set(preparedRoute.route.path, preparedRoute);
    } else if (depth === currentDepth) {
      warnPathCollision(preparedRoute, current);
    }
  }

  return sortedRoutes([...byPath.values()]);
}

function renderValidatorImports(validators: PreparedSearchRoute['validators']) {
  return `[${validators
    .map(
      (validator) =>
        `() => import(${JSON.stringify(validator.file.split(path.sep).join('/'))}).then(module => module.validateSearch)`,
    )
    .join(', ')}]`;
}

/**
 * Render the generated `SearchRouteRegistry` and codec augmentation.
 *
 * The deepest route wins for duplicate URL patterns; equal-depth collisions
 * are warned because typed helpers can expose only one contract per path.
 */
export function renderTypeRegistry(
  routes: ReadonlyArray<PreparedSearchRoute>,
  outputFile: string,
  codec: SearchCodecName = DEFAULT_SEARCH_CODEC,
): string {
  const entries = deepestRoutesByPath(routes).map(
    ({ route, validators }) =>
      `    ${JSON.stringify(route.path)}: readonly [${validators
        .map(
          (validator) =>
            `typeof import(${JSON.stringify(moduleSpecifier(outputFile, validator.file))}).validateSearch`,
        )
        .join(', ')}];`,
  );

  return (
    `// Generated by react-router-validated-search. Do not edit.\n\n` +
    `import 'react-router-validated-search';\n\n` +
    `declare module 'react-router-validated-search' {\n` +
    `  interface SearchRouteRegistry {\n${entries.join('\n')}\n  }\n` +
    `  interface SearchCodecRegister {\n    codec: ${JSON.stringify(codec)};\n  }\n` +
    `}\n`
  );
}

/** Render lazy validator imports indexed by URL pattern and route id. */
export function renderRuntimeRegistry(routes: ReadonlyArray<PreparedSearchRoute>): string {
  const pathEntries = deepestRoutesByPath(routes).map(
    ({ route, validators }) =>
      `  ${JSON.stringify(route.path)}: ${renderValidatorImports(validators)}`,
  );
  const routeEntries = sortedRoutes(routes).map(
    ({ route, validators }) =>
      `  ${JSON.stringify(route.id)}: ${renderValidatorImports(validators)}`,
  );

  return (
    `export const validatorImportsByRoutePattern = {\n${pathEntries.join(',\n')}\n};\n\n` +
    `export const validatorImportsByRouteId = {\n${routeEntries.join(',\n')}\n};\n`
  );
}
